#!/usr/bin/env bash
# Optional local data stack (PostgreSQL + Redis + Adminer) in Docker.

install_databases() {
    [[ ${WITH_DB} -eq 1 ]] || return 0

    local dir=/opt/wsl-stack
    install -d -m 0755 -o "$TARGET_USER" -g "$TARGET_USER" "$dir"
    install -m 0644 -o "$TARGET_USER" -g "$TARGET_USER" \
        "${SCRIPT_DIR}/docker/compose.yaml" "${dir}/compose.yaml"

    if [[ ! -f ${dir}/.env ]]; then
        local password
        password=$(openssl rand -hex 16 2>/dev/null || tr -dc 'a-f0-9' </dev/urandom | head -c 32)
        cat >"${dir}/.env" <<EOF
# Generated by wsl-provision on $(date -u +%Y-%m-%dT%H:%M:%SZ)
POSTGRES_USER=app
POSTGRES_DB=app
POSTGRES_PASSWORD=${password}
EOF
        chown "$TARGET_USER:$TARGET_USER" "${dir}/.env"
        chmod 0600 "${dir}/.env"
        ok "credentials written to ${dir}/.env (mode 600)"
    else
        ok "existing ${dir}/.env kept"
    fi

    ok "stack available at ${dir} (docker compose --profile tools up -d)"

    if [[ ${START_DB} -eq 1 ]]; then
        info "Starting the data stack"
        if run_as_user "$TARGET_USER" "cd ${dir} && docker compose up -d" >/dev/null 2>&1; then
            ok "postgres, redis and adminer are up"
        else
            warn "docker compose failed; run it manually to see the error"
        fi
    fi
}
